   "headingLine": 2341,
   "startLine": 2342,
   "endLine": 2551,
   "heading": "AN ADJUSTMENT OF NATURE",
   "bodySha256": "a86142940d398d78536d909d440cb30a50d34ac16f6f00c6589ebcaca4ab333e"
